export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    try {
      const saved = window.localStorage.getItem('portfolio-language');
      return ['en', 'fr', 'ar'].includes(saved) ? saved : 'en';
    } catch { return 'en'; }
  });

  useEffect(() => {
    const root = document.documentElement;
    root.lang = language;
    root.dir = language === 'ar' ? 'rtl' : 'ltr';
    document.title = translations[language]?.['Mohamed Yahya Sellami | Full-Stack, IoT & Software Testing'] || 'Mohamed Yahya Sellami | Full-Stack, IoT & Software Testing';
    try { window.localStorage.setItem('portfolio-language', language); } catch { /* Language selection remains active for this tab. */ }
  }, [language]);

  const value = useMemo(() => ({
    language,
    setLanguage,
    t: (text) => galleryTranslations[language]?.[text] || supplemental[language]?.[text] || translations[language]?.[text] || text,
  }), [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within a LanguageProvider');
  return context;
}
